let timer = null;
let dotNetRef = null;
let isIdle = false;
let timeoutMs = 0;
let listeners = [];

function resetTimer() {
    clearTimeout(timer);

    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnActiveCallback");
    }

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, timeoutMs);
}

export function initialize(element, ref, timeoutSeconds) {
    dotNetRef = ref;
    timeoutMs = timeoutSeconds * 1000;
    isIdle = false;

    const events = ["mousemove", "keydown", "click", "scroll", "touchstart"];

    events.forEach(evt => {
        const handler = () => resetTimer();
        element.addEventListener(evt, handler, { passive: true });
        listeners.push({ element, evt, handler });
    });

    timer = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnIdleCallback");
    }, timeoutMs);
}

export function dispose() {
    clearTimeout(timer);
    timer = null;

    listeners.forEach(({ element, evt, handler }) => {
        element.removeEventListener(evt, handler);
    });
    listeners = [];

    dotNetRef = null;
    isIdle = false;
}

